      "proposed_laureates": [
        "Charles L. Kane",
        "Eugene J. Mele",
        "Laurens W. Molenkamp"
      ],
      "assessment": {
        "nobel_worthiness": "The quantum spin Hall effect and topological-insulator framework disclosed a durable new class of quantum matter and transformed condensed-matter physics.",
        "attribution": "Kane and Mele supplied the decisive theoretical concept, while Molenkamp provided a landmark experimental realization in a quantum well.",
        "maturity": "The topological classification, protected boundary physics, and material realizations have been extensively reproduced and developed.",
        "uncertainties": [
          "The experimental credit landscape includes important contributions beyond the named quantum-well realization."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B026",
      "proposed_laureates": [
        "Antoine Georges",
        "Dieter Vollhardt",
        "Gabriel Kotliar"
      ],
      "assessment": {
        "nobel_worthiness": "Dynamical mean-field theory made strongly correlated electrons quantitatively tractable and gave a broadly useful account of correlation-driven spectral and phase behavior.",
        "attribution": "Vollhardt established the infinite-dimensional foundation, while Georges and Kotliar were central to the practical and conceptual formulation that became DMFT.",
        "maturity": "It is a mature, widely benchmarked framework tightly connected to spectroscopy and realistic materials calculations.",
        "uncertainties": [
          "The development involved several related formulations and a broad methodological community."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B008",
      "proposed_laureates": [
        "Jagadeesh S. Moodera",
        "Stuart S. P. Parkin",
        "Terunobu Miyazaki"
      ],
      "assessment": {
        "nobel_worthiness": "Room-temperature tunnel magnetoresistance made coherent spin-dependent tunnelling a powerful physical effect and enabled modern spintronic memory technologies.",
        "attribution": "Moodera and Miyazaki made seminal demonstrations of large magnetoresistance, and Parkin was pivotal in establishing MgO junctions of technological quality.",
        "maturity": "The phenomenon is quantitatively understood, reproducible, and deployed at large scale in magnetic memory.",
        "uncertainties": [
          "The historical path includes earlier tunnelling work and multiple groups important to MgO-junction optimization."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B003",
      "proposed_laureates": [
        "Pablo Jarillo-Herrero",
        "Allan H. MacDonald",
        "Rafi Bistritzer"
      ],
      "assessment": {
        "nobel_worthiness": "Magic-angle graphene revealed an exceptionally tunable platform in which band geometry and correlations generate unexpected insulating and superconducting states.",
        "attribution": "Bistritzer and MacDonald identified the magic-angle flat-band mechanism, and Jarillo-Herrero's group made the catalytic experimental discovery.",
        "maturity": "The moiré platform and flat-band physics are firmly established and have stimulated many independently investigated material systems.",
        "uncertainties": [
          "The microscopic origin and universality of superconductivity remain unsettled.",
          "Device sensitivity and sample-dependent phase diagrams complicate a definitive attribution."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B062",
      "proposed_laureates": [
        "Harald Rose",
        "Knut Urban",
        "Maximilian Haider"
      ],
      "assessment": {
        "nobel_worthiness": "Spherical-aberration correction changed electron microscopy from a resolution-limited imaging tool into a quantitative probe of matter at the atomic scale.",
        "attribution": "Rose provided foundational correction concepts, while Haider and Urban were central to their practical realization and materials-science impact.",
        "maturity": "Aberration-corrected microscopy is a mature, independently validated capability integral to modern materials research.",
        "uncertainties": [
          "Its development depended on substantial contributions in electron optics, instrumentation, and software beyond three individuals."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B033",
      "proposed_laureates": [
        "Bart J. van Wees",
        "David A. Wharam",
        "Michael Pepper"
      ],
      "assessment": {
        "nobel_worthiness": "The observation of quantized conductance gave a striking, direct manifestation of quantum transport in mesoscopic conductors.",
        "attribution": "The nearly simultaneous Dutch and UK experiments established the effect; van Wees, Wharam, and Pepper represent the central experimental credit.",
        "maturity": "The conductance quantum and its Landauer interpretation have been confirmed across many mesoscopic systems and underpin quantum-transport science.",
        "uncertainties": [
          "The near-simultaneous discoveries make the precise allocation of experimental credit difficult."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B006",
      "proposed_laureates": [
        "Alfred Y. Cho",
        "Federico Capasso",
        "Jérôme Faist"
      ],
      "assessment": {
        "nobel_worthiness": "The quantum cascade laser established a new semiconductor-laser principle based on engineered intersubband transitions and has had major scientific and practical consequences.",
        "attribution": "Cho enabled the heterostructure technology, Capasso developed the key band-structure engineering ideas, and Faist led the seminal device realization.",
        "maturity": "Quantum cascade lasers are technologically mature and broadly used in infrared spectroscopy, sensing, and communications.",
        "uncertainties": [
          "The invention rests on a longer sequence of heterostructure and intersubband-physics advances."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B037",
      "proposed_laureates": [
        "Eli Yablonovitch",
        "Sajeev John",
        "Susumu Noda"
      ],
      "assessment": {
        "nobel_worthiness": "Photonic band gaps supplied a deep materials-style approach to controlling light, with lasting influence on nanophotonics and quantum optical devices.",
        "attribution": "John and Yablonovitch introduced decisive theoretical and experimental directions, while Noda made major advances toward controllable photonic-crystal structures and devices.",
        "maturity": "Photonic-crystal physics is mature and experimentally robust, with extensive applications and a well-developed theoretical foundation.",
        "uncertainties": [
          "The field's broad distributed development makes a three-person attribution necessarily selective."
        ]
      }
    }
  ]
